package org.beckenburg.editor;

import java.util.*;
import org.beckenburg.editor.EditorTopologyProject.*;
import org.beckenburg.editor.EditorMeshPipeline.Normal;

/** One native convex support-edge/corner plane cut, retaining exact original attributes outside the cut. */
final class EditorMeshBevel {
    private EditorMeshBevel(){}
    private record Edge(long a,long b){static Edge of(long a,long b){return new Edge(Math.min(a,b),Math.max(a,b));}}
    private record Cut(long id,double t){}
    private static double dot(Normal n,double x,double y,double z){return n.x()*x+n.y()*y+n.z()*z;}
    private static double cross(Normal n,Vertex a,Vertex b,Vertex c){double x=b.x()-a.x(),y=b.y()-a.y(),z=b.z()-a.z(),u=c.x()-a.x(),v=c.y()-a.y(),w=c.z()-a.z();return dot(n,y*w-z*v,z*u-x*w,x*v-y*u);}
    private static EditorMeshPipeline.Vertex v(Vertex v){return new EditorMeshPipeline.Vertex(v.x(),v.y(),v.z(),0,0);}
    private static Normal normal(Face face,Map<Long,Vertex> points){return EditorMeshNormals.face(new EditorMeshPipeline.Triangle(face.part(),v(points.get(face.a().vertex())),v(points.get(face.b().vertex())),v(points.get(face.c().vertex()))));}
    static State build(State before,Set<Long> selected,long activeFace,double depth){
        if(selected.isEmpty()||selected.size()>2||!Double.isFinite(depth)||depth<=0||depth>10000)throw new IllegalArgumentException("Bevel cut depth must be positive and at most 10000");
        var points=new LinkedHashMap<Long,Vertex>();for(var vertex:before.vertices())points.put(vertex.id(),vertex);String part=null;double ox=0,oy=0,oz=0;for(long id:selected){var vertex=points.get(id);if(vertex==null)throw new IllegalArgumentException("Unknown native bevel vertex");if(part!=null&&!part.equals(vertex.part()))throw new IllegalArgumentException("Bevel endpoints must belong to one native part");part=vertex.part();ox+=vertex.x()/selected.size();oy+=vertex.y()/selected.size();oz+=vertex.z()/selected.size();}
        Face active=null;var incident=new ArrayList<Face>();for(var face:before.faces()){
            var corners=List.of(face.a(),face.b(),face.c());int count=0;for(var corner:corners)if(selected.contains(corner.vertex()))count++;
            if(count==selected.size())incident.add(face);if(face.id()==activeFace){active=face;if(count!=selected.size())throw new IllegalArgumentException("Active face does not own the selected bevel edge/corner");}
        }
        if(active==null)throw new IllegalArgumentException("Pick an active native face for bevel material and orientation");if(selected.size()==2&&incident.size()!=2||selected.size()==1&&incident.size()<3)throw new IllegalArgumentException("Bevel requires a closed manifold edge or corner");
        double nx=0,ny=0,nz=0;for(var face:incident){var n=normal(face,points);double weight=1;if(selected.size()==1){long id=selected.iterator().next();var corners=List.of(face.a(),face.b(),face.c());int index=0;while(corners.get(index).vertex()!=id)index++;var a=points.get(corners.get(index).vertex());var b=points.get(corners.get((index+1)%3).vertex());var c=points.get(corners.get((index+2)%3).vertex());var u=EditorMeshNormals.unit(new Normal(b.x()-a.x(),b.y()-a.y(),b.z()-a.z()));var v=EditorMeshNormals.unit(new Normal(c.x()-a.x(),c.y()-a.y(),c.z()-a.z()));weight=Math.acos(Math.max(-1,Math.min(1,dot(u,v.x(),v.y(),v.z()))));}nx+=n.x()*weight;ny+=n.y()*weight;nz+=n.z()*weight;}
        if(selected.size()==2){double cosine=dot(normal(incident.get(0),points),normal(incident.get(1),points).x(),normal(incident.get(1),points).y(),normal(incident.get(1),points).z());if(cosine>=1-1e-10)throw new IllegalArgumentException("Coplanar triangulation diagonals are not bevel edges");}
        var outward=EditorMeshNormals.unit(new Normal(nx,ny,nz));double tolerance=Math.max(Math.max(Math.ulp(Math.abs(ox)),Math.max(Math.ulp(Math.abs(oy)),Math.ulp(Math.abs(oz))))*64,Math.max(Math.ulp(depth)*64,depth*1e-10));
        for(var vertex:before.vertices())if(vertex.part().equals(part)){double distance=dot(outward,vertex.x()-ox,vertex.y()-oy,vertex.z()-oz);if(selected.contains(vertex.id())){if(Math.abs(distance)>tolerance)throw new IllegalArgumentException("Selected bevel edge does not lie on its support plane");}else if(distance>=-depth-tolerance)throw new IllegalArgumentException("Bevel plane would cut another native vertex; choose a smaller depth on a convex edge/corner");}
        long nextVertex=before.vertices().stream().mapToLong(Vertex::id).max().orElse(-1)+1,nextFace=before.faces().stream().mapToLong(Face::id).max().orElse(-1)+1;if(nextVertex<0||nextFace<0)throw new IllegalArgumentException("Native bevel identity budget exceeded");
        var cuts=new LinkedHashMap<Edge,Cut>();var cutIds=new HashSet<Long>();var capEdges=new LinkedHashMap<Long,Long>();var capIncoming=new HashSet<Long>();var faces=new ArrayList<Face>();var allPoints=new LinkedHashMap<>(points);
        for(var face:before.faces()){
            var original=List.of(face.a(),face.b(),face.c());if(!face.part().equals(part)||original.stream().noneMatch(c->selected.contains(c.vertex()))){faces.add(face);continue;}
            var polygon=new ArrayList<Corner>();var faceNormal=normal(face,points);
            for(int i=0;i<3;i++){var a=original.get((i+2)%3);var b=original.get(i);boolean outsideA=selected.contains(a.vertex()),outsideB=selected.contains(b.vertex());if(outsideA!=outsideB){var edge=Edge.of(a.vertex(),b.vertex());Cut cut=cuts.get(edge);if(cut==null){if(nextVertex==Long.MAX_VALUE||allPoints.size()>=EditorMeshPipeline.MAX_TRIANGLES*3)throw new IllegalArgumentException("Native bevel vertex budget exceeded");var start=points.get(edge.a());var end=points.get(edge.b());double da=dot(outward,start.x()-ox,start.y()-oy,start.z()-oz)+depth,db=dot(outward,end.x()-ox,end.y()-oy,end.z()-oz)+depth,t=da/(da-db);if(!(t>0&&t<1)||!Double.isFinite(t))throw new IllegalArgumentException("Invalid native bevel intersection");cut=new Cut(nextVertex++,t);cuts.put(edge,cut);cutIds.add(cut.id());allPoints.put(cut.id(),new Vertex(cut.id(),part,start.x()+(end.x()-start.x())*t,start.y()+(end.y()-start.y())*t,start.z()+(end.z()-start.z())*t));}
                    double t=a.vertex()==edge.a()?cut.t():1-cut.t();Normal blended=null;if(a.normal()!=null||b.normal()!=null){var na=a.normal()==null?faceNormal:EditorMeshNormals.unit(a.normal());var nb=b.normal()==null?faceNormal:EditorMeshNormals.unit(b.normal());blended=EditorMeshNormals.unit(new Normal(na.x()+(nb.x()-na.x())*t,na.y()+(nb.y()-na.y())*t,na.z()+(nb.z()-na.z())*t));}polygon.add(new Corner(cut.id(),a.u()+(b.u()-a.u())*t,a.v()+(b.v()-a.v())*t,blended));}
                if(!outsideB)polygon.add(b);
            }
            if(polygon.size()<3||polygon.size()>4)throw new IllegalArgumentException("Invalid clipped native bevel face");
            for(int i=0;i<polygon.size();i++){long a=polygon.get(i).vertex(),b=polygon.get((i+1)%polygon.size()).vertex();if(cutIds.contains(a)&&cutIds.contains(b)){if(capEdges.putIfAbsent(b,a)!=null||!capIncoming.add(a))throw new IllegalArgumentException("Native bevel cut has a branched boundary");}}
            for(int i=1;i+1<polygon.size();i++){long id=i==1?face.id():nextFace++;if(id<0||nextFace<0)throw new IllegalArgumentException("Native bevel identity budget exceeded");faces.add(new Face(id,part,polygon.get(0),polygon.get(i),polygon.get(i+1),face.material()));}
        }
        if(capEdges.size()<3||capEdges.size()!=cuts.size())throw new IllegalArgumentException("Native bevel cut must form one closed boundary");long start=capEdges.keySet().stream().mapToLong(Long::longValue).min().orElseThrow(),id=start;var ring=new ArrayList<Long>();do{if(ring.size()>=capEdges.size())throw new IllegalArgumentException("Native bevel boundary is disconnected");ring.add(id);Long next=capEdges.get(id);if(next==null)throw new IllegalArgumentException("Native bevel boundary is open");id=next;}while(id!=start);if(ring.size()!=capEdges.size())throw new IllegalArgumentException("Native bevel cut has multiple boundaries");
        var edge=selected.size()==2?selected.stream().sorted().map(points::get).toList():List.of(points.get(active.a().vertex()),points.get(active.b().vertex()));var a=edge.get(0);var b=edge.get(1);var tangent=EditorMeshNormals.unit(new Normal(b.x()-a.x(),b.y()-a.y(),b.z()-a.z()));double projection=dot(outward,tangent.x(),tangent.y(),tangent.z());tangent=EditorMeshNormals.unit(new Normal(tangent.x()-outward.x()*projection,tangent.y()-outward.y()*projection,tangent.z()-outward.z()*projection));var bitangent=new Normal(outward.y()*tangent.z()-outward.z()*tangent.y(),outward.z()*tangent.x()-outward.x()*tangent.z(),outward.x()*tangent.y()-outward.y()*tangent.x());
        var capCorners=new HashMap<Long,Corner>();for(long vertex:ring){var p=allPoints.get(vertex);capCorners.put(vertex,new Corner(vertex,dot(tangent,p.x()-ox,p.y()-oy,p.z()-oz),dot(bitangent,p.x()-ox,p.y()-oy,p.z()-oz),null));}
        int work=0;while(ring.size()>3){boolean found=false;for(int i=0;i<ring.size();i++){if(++work>5_000_000)throw new IllegalArgumentException("Native bevel cap work budget exceeded");long pa=ring.get((i+ring.size()-1)%ring.size()),pb=ring.get(i),pc=ring.get((i+1)%ring.size());var va=allPoints.get(pa);var vb=allPoints.get(pb);var vc=allPoints.get(pc);double area=cross(outward,va,vb,vc);if(area<=tolerance*tolerance)continue;boolean blocked=false;for(long vertex:ring)if(vertex!=pa&&vertex!=pb&&vertex!=pc){if(++work>5_000_000)throw new IllegalArgumentException("Native bevel cap work budget exceeded");var p=allPoints.get(vertex);if(cross(outward,va,vb,p)>=-tolerance*tolerance&&cross(outward,vb,vc,p)>=-tolerance*tolerance&&cross(outward,vc,va,p)>=-tolerance*tolerance){blocked=true;break;}}if(blocked)continue;if(nextFace==Long.MAX_VALUE)throw new IllegalArgumentException("Native bevel identity budget exceeded");faces.add(new Face(nextFace++,part,capCorners.get(pa),capCorners.get(pb),capCorners.get(pc),active.material()));ring.remove(i);found=true;break;}if(!found)throw new IllegalArgumentException("Native bevel cap cannot be triangulated without degeneracy");}
        if(cross(outward,allPoints.get(ring.get(0)),allPoints.get(ring.get(1)),allPoints.get(ring.get(2)))<=tolerance*tolerance)throw new IllegalArgumentException("Degenerate native bevel cap");faces.add(new Face(nextFace,part,capCorners.get(ring.get(0)),capCorners.get(ring.get(1)),capCorners.get(ring.get(2)),active.material()));
        var used=new HashSet<Long>();for(var face:faces){used.add(face.a().vertex());used.add(face.b().vertex());used.add(face.c().vertex());}var vertices=new ArrayList<Vertex>();for(var vertex:allPoints.values())if(!selected.contains(vertex.id())||used.contains(vertex.id()))vertices.add(vertex);if(faces.size()>EditorMeshPipeline.MAX_TRIANGLES||vertices.size()>EditorMeshPipeline.MAX_TRIANGLES*3)throw new IllegalArgumentException("Native bevel exceeds topology budget");
        return new State(before.sceneId(),before.sourceFingerprint(),before.name(),before.sourceBytes(),vertices,faces,before.materials(),before.glbSource(),EditorMeshFrame.retain(before.frames(),vertices));
    }
}
